package com.fasterxml.jackson.databind;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.annotation.JsonFormat;
import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.cfg.*;
import com.fasterxml.jackson.databind.cfg.MapperFeature;
import com.fasterxml.jackson.databind.cfg.VisibilityChecker;
import com.fasterxml.jackson.databind.deser.DeserializationProblemHandler;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.introspect.SimpleMixInResolver;
import com.fasterxml.jackson.databind.introspect.SubtypeResolver;
import com.fasterxml.jackson.databind.jsontype.*;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.LinkedNode;
import com.fasterxml.jackson.databind.util.RootNameLookup;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.util.*;
import org.junit.*;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for DeserializationConfig#getDefaultVisibilityChecker
 */
public class DeserializationConfig_getDefaultVisibilityChecker_TriageGen2Test {

    private BaseSettings baseSettings;
    private SubtypeResolver subtypeResolver;
    private SimpleMixInResolver mixins;
    private RootNameLookup rootNames;

    @BeforeEach
    public void setUp() {
        baseSettings = Mockito.mock(BaseSettings.class);
        subtypeResolver = Mockito.mock(SubtypeResolver.class);
        mixins = Mockito.mock(SimpleMixInResolver.class);
        rootNames = Mockito.mock(RootNameLookup.class);
    }

    /**
     * Test Case 1: All AUTO_DETECT features are enabled.
     * The visibility checker should remain unchanged from the super class implementation.
     */
    @Test
    public void testGetDefaultVisibilityChecker_AllFeaturesEnabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(MapperFeature.AUTO_DETECT_SETTERS)
                .with(MapperFeature.AUTO_DETECT_CREATORS)
                .with(MapperFeature.AUTO_DETECT_FIELDS);

        // We need to mock the behavior of isEnabled for the specific features
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        // Since we can't easily check the internal state of the super VisibilityChecker without 
        // knowing the exact default, we verify that the visibility is NOT NONE (assuming defaults are higher)
        // or simply that the logic path for 'if (!isEnabled)' was not taken.
        // In a real Jackson environment, the default visibility is usually anything but NONE.
        assertEquals(Visibility.ANY, checker.getGetterVisibility()); 
    }

    /**
     * Test Case 2: AUTO_DETECT_SETTERS is disabled.
     * Setter visibility should be set to NONE.
     */
    @Test
    public void testGetDefaultVisibilityChecker_DisableSetters() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .without(MapperFeature.AUTO_DETECT_SETTERS)
                .with(MapperFeature.AUTO_DETECT_CREATORS)
                .with(MapperFeature.AUTO_DETECT_FIELDS);

        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(false);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        assertEquals(Visibility.ANY, checker.getGetterVisibility()); // Should remain default
    }

    /**
     * Test Case 3: AUTO_DETECT_CREATORS is disabled.
     * Creator visibility should be set to NONE.
     */
    @Test
    public void testGetDefaultVisibilityChecker_DisableCreators() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(MapperFeature.AUTO_DETECT_SETTERS)
                .without(MapperFeature.AUTO_DETECT_CREATORS)
                .with(MapperFeature.AUTO_DETECT_FIELDS);

        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(false);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(true);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getConstructorVisibility());
        assertEquals(Visibility.ANY, checker.getGetterVisibility());
    }

    /**
     * Test Case 4: AUTO_DETECT_FIELDS is disabled.
     * Field visibility should be set to NONE.
     */
    @Test
    public void testGetDefaultVisibilityChecker_DisableFields() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .with(MapperFeature.AUTO_DETECT_SETTERS)
                .with(MapperFeature.AUTO_DETECT_CREATORS)
                .without(MapperFeature.AUTO_DETECT_FIELDS);

        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(true);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(false);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getFieldVisibility());
        assertEquals(Visibility.ANY, checker.getGetterVisibility());
    }

    /**
     * Test Case 5: All features disabled.
     * All visibilities should be set to NONE.
     */
    @Test
    public void testGetDefaultVisibilityChecker_AllDisabled() {
        DeserializationConfig config = new DeserializationConfig(baseSettings, subtypeResolver, mixins, rootNames)
                .without(MapperFeature.AUTO_DETECT_SETTERS)
                .without(MapperFeature.AUTO_DETECT_CREATORS)
                .without(MapperFeature.AUTO_DETECT_FIELDS);

        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_SETTERS)).thenReturn(false);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_CREATORS)).thenReturn(false);
        Mockito.when(baseSettings.isEnabled(MapperFeature.AUTO_DETECT_FIELDS)).thenReturn(false);

        VisibilityChecker<?> checker = config.getDefaultVisibilityChecker();

        assertEquals(Visibility.NONE, checker.getSetterVisibility());
        assertEquals(Visibility.NONE, checker.getConstructorVisibility());
        assertEquals(Visibility.NONE, checker.getFieldVisibility());
    }
}
